script:
frappe.ui.form.on("OT Event", {
	refresh(frm) {
		if (!frm.is_new()) { return; }

		frappe.db.get_list("OT Constituent", {
		    fields: ["name", "preferred_name", "last_name"]
		}).then(constituents => {
		    constituents.forEach(constituent => {
		        frm.add_child("event_participants", {
		            reference_doctype: "OT Constituent",
		            reference_docname: constituent.name,
		            participant: `${constituent.preferred_name} ${constituent.last_name}`
		        })
		    });

		    frm.refresh_field("event_participants")
		})
	}
})

frappe.ui.form.on('OT Event', {
    refresh(frm) {
        frm.add_custom_button("Invite Constituents", () => {
            new frappe.ui.form.MultiSelectDialog({
                doctype: "OT Constituent",
                target: frm,
                setters: {},
                get_query() {
                    return {
                        query: "organizer_toolkit.api.fetch_ot_constituents"
                    };
                },
                add_filters_group: 1,
                date_field: "creation",
                columns: ["full_name", "type", "postal_code"],
                action(selected_constituents) {
                    selected_constituents.forEach(constituent => {
                        frappe.db.get_doc("OT Constituent", constituent).then(constituent_doc => {
                            let rsvp = frappe.model.add_child(constituent_doc, "event_rsvps");
                            rsvp.event = frm.doc.name;

                            frm.refresh_field("event_rsvps");
                        });
                    });
                }
            });
        });
    }
});

frappe.ui.form.on("OT Event", {
  refresh: function(frm) {
    console.log("Inside refresh function");

    if (frm.fields_dict['rsvphtml']) {
      var cur_field = frm.fields_dict['rsvphtml'];
      console.log("cur_field found:", cur_field);

      // Function to fetch rsvps
      function fetch_rsvps(start, limit) {
        console.log("Fetching rsvps from start:", start, "with limit:", limit);
        frappe.call({
          method: "frappe.client.get_list",
          args: {
            doctype: "OT Constituent",
            filters: [["OT Event RSVP","event", "=", frm.doc.name]],
            fields: ["first_name","last_name","mobile_phone"],
            limit_start: start,
            limit_page_length: limit,
          },
          callback: function(response) {
            console.log("Response received:", response);
            if (!response.message || response.message.length === 0) {
              cur_field.html("No linked rsvps found for this Event.");
              return;
            }

            try {
              var rsvp_list_html = get_rsvp_list_html(response.message);
              cur_field.$wrapper.html(rsvp_list_html); // Set the HTML
              add_pagination_controls(cur_field.$wrapper, start, limit, response.message.length);
            } catch (error) {
              console.error("Error generating HTML:", error);
              cur_field.$wrapper.html("Failed to display linked rsvps.");
            }
          },
          error: function(error) {
            console.error("Error in frappe call:", error);
            cur_field.$wrapper.html("Failed to fetch linked rsvps.");
          }
        });
      }

      // Initial fetch with page 1
      fetch_rsvps(0, 10);
    } else {
      console.error("Custom field 'rsvphtml' not found.");
    }
  },
});

// Function to generate HTML
function get_rsvp_list_html(data) {
  try {
    var table_html = '<div class="table-responsive"><table class="table table-bordered">';
    table_html += "<thead><tr>";
    table_html += "<th>First Name</th><th>Last Name</th><th>Mobile Phone</th>"; // Add table headers
    table_html += "</tr></thead><tbody>";

    // Iterate through fetched rsvps and build table rows
    data.forEach(rsvp => {
      table_html += "<tr>";
      table_html += `<td>${rsvp.first_name || ""}</td>`;
      table_html += `<td>${rsvp.last_name || ""}</td>`;
      table_html += `<td>${rsvp.mobile_phone || ""}</td>`;
      table_html += "</tr>";
    });

    table_html += "</tbody></table></div>";
    return table_html;
  } catch (error) {
    console.error("Error in get_rsvp_list_html function:", error);
    throw error;
  }
}

// Function to add pagination controls
function add_pagination_controls(container, start, limit, fetched_count) {
  try {
    container = $(container); // Ensure container is a jQuery object
    var pagination_html = '<div class="pagination-controls">';
    if (start > 0) {
      pagination_html += `<button class="btn btn-secondary" onclick="fetch_rsvps(${start - limit}, ${limit})">Previous</button>`;
    }
    if (fetched_count === limit) {
      pagination_html += `<button class="btn btn-secondary" onclick="fetch_rsvps(${start + limit}, ${limit})">Next</button>`;
    }
    pagination_html += '</div>';
    container.append(pagination_html);
  } catch (error) {
    console.error("Error in add_pagination_controls function:", error);
    throw error;
  }
}

// Make fetch_rsvps globally accessible
window.fetch_rsvps = function(start, limit) {
  var frm = cur_frm; // Use the global cur_frm object
  if (frm.fields_dict['rsvphtml']) {
    var cur_field = frm.fields_dict['rsvphtml'];
    console.log("Fetching rsvps for pagination from start:", start, "with limit:", limit);
    frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: "OT Constituent",
        filters: [["OT Event RSVP","event", "=", frm.doc.name]],
        fields: ["first_name","last_name","mobile_phone"],
        limit_start: start,
        limit_page_length: limit,
      },
      callback: function(response) {
        console.log("Pagination response received:", response);
        if (!response.message || response.message.length === 0) {
          cur_field.$wrapper.html("No linked rsvps found for this Event.");
          return;
        }

        try {
          var rsvp_list_html = get_rsvp_list_html(response.message);
          cur_field.$wrapper.html(rsvp_list_html); // Set the HTML
          add_pagination_controls(cur_field.$wrapper, start, limit, response.message.length);
        } catch (error) {
          console.error("Error generating HTML for pagination:", error);
          cur_field.$wrapper.html("Failed to display linked rsvps.");
        }
      },
      error: function(error) {
        console.error("Error in frappe call for pagination:", error);
        cur_field.$wrapper.html("Failed to fetch linked rsvps.");
      }
    });
  } else {
    console.error("Custom field 'rsvphtml' not found.");
  }
};

frappe.ui.form.on('OT Event', {
    refresh(frm) {
        if (frm.is_new()) { return; }

        frm.add_custom_button("Invite Constituents", () => {
            new frappe.ui.form.MultiSelectDialog({
                doctype: "OT Constituent",
                target: frm,
                setters: {},
                get_query() {
                    return {
                        query: "organizer_toolkit.api.fetch_ot_constituents"
                    };
                },
                add_filters_group: 1,
                date_field: "creation",
                columns: ["full_name", "type", "postal_code"],
                primary_action_label: __("Add Constituents"),
                action(selected_constituents) {
                    selected_constituents.forEach(constituent => {
                        frappe.model.with_doc("OT Constituent", constituent, function () {
                            let constituent_doc = frappe.model.get_doc("OT Constituent", constituent);
                            let rsvp = frappe.model.add_child(constituent_doc, "event_rsvps");
                            rsvp.event = frm.doc.name;

                            frappe.call({
                                method: "frappe.desk.form.save.savedocs",
                                args: {
                                    doc: constituent_doc,
                                    action: "Save"
                                },
                                callback: function(r) { }
                            });


                        });
                    });

                    this.dialog.hide();

                    frm.refresh_field("rsvphtml");
                }
            });
        });
    }
});

frappe.ui.form.on('OT Constituent', {
	validate: async function(frm) {
	    if (!frm.doc.__save_form && frm.is_new()) {
    		const first_name = frm.doc.first_name;
    		const last_name = frm.doc.last_name;
    		const street_address = frm.doc.street_address;

    		const response = await frappe.call(
    		    "organizer_toolkit.api.compare_against_name_and_address",
    		    {
    		        first_name: first_name,
    		        last_name: last_name,
    		        street_address: street_address
    		    }
    	    );

	        const similar_constituents = response.message;

	        if (similar_constituents.length > 0) {
	            let d = new frappe.ui.Dialog({
	                title: `Similar constituent(s) exist! Did you mean to edit one of these:`,
	                fields: similar_constituents.map(constituent => {
	                    const label = `${constituent.first_name} ${constituent.last_name} ${constituent.street_address}`;
	                    const fieldName = constituent.name;
	                    return {
	                        label: label,
	                        fieldname: fieldName,
	                        fieldtype: 'Check'
	                    }
	                }),
	                primary_action_label: "Edit",
	                primary_action(constituents) {
	                    d.hide();

	                    let set_route = false;
    	                let set_target = "";

	                    for (const constituent in constituents) {
	                        if (constituents.hasOwnProperty(constituent) && constituents[constituent] === 1) {
	                            set_route = true;
	                            set_target = constituent;
	                            break;
	                        }
	                    }

	                    if (set_route) {
	                        delete frm.doc.__save_form;

                            frappe.validated = false;
                            frappe.set_route("Form", "OT Constituent", set_target);

                            return false;
                        } else {
                            frm.doc.__save_form = true;
                            frm.save();
                        }
	                }
	            });

	            frappe.validated = false;

	            d.show();

	            return false;
    	    }

    	    frm.doc.__save_form = true;
    	    frm.save();
	    } 

	    delete frm.doc.__save_form;
    }
});

frappe.ui.form.on('OT Constituent', {
	refresh(frm) {
		frm.trigger("count_events_attended");
	},

	event_rsvps_remove: function(frm) {
	    frm.trigger("count_events_attended");
	},

	count_events_attended: function(frm) {
	    let attending = 0;

	    if (frm.doc.event_rsvps && frm.doc.event_rsvps.length > 0) {
	        frm.doc.event_rsvps.forEach(event => {
	            if (event.rsvp === "Yes") {
	                attending += 1;
	            }
	        })
	    }

	    if (attending > 0) {
    	    frm.set_value("events_attending", attended);
    	    frm.refresh_field("events_attending");
    	    frm.save()
	    }
	}
})
